template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{40} \def\angleb{130} \def\anglec{215} \def\angled{300} \def\showcenter{1} \def\showdiagonals{0} \def\showanglea{0} \def\showanglec{0} \def\showexterior{0} \def\labela{A} \def\labelb{B} \def\labelc{C} \def\labeld{D} \def\labele{E}
% 视觉归一化：把圆直径缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% 四个顶点按位置角逆时针依次排列（约束已保证 anglea<angleb<anglec<angled 且互相拉开，四边形凸而不退化）
\pgfmathsetmacro{\Ax}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ay}{\radius*sin(\anglea)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angleb)}
\pgfmathsetmacro{\By}{\radius*sin(\angleb)}
\pgfmathsetmacro{\Cx}{\radius*cos(\anglec)}
\pgfmathsetmacro{\Cy}{\radius*sin(\anglec)}
\pgfmathsetmacro{\Dx}{\radius*cos(\angled)}
\pgfmathsetmacro{\Dy}{\radius*sin(\angled)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (\Ax,\Ay);
  \coordinate (B) at (\Bx,\By);
  \coordinate (C) at (\Cx,\Cy);
  \coordinate (D) at (\Dx,\Dy);
  % 外接圆
  \draw[thick] (O) circle [radius=\radius];
  % 圆内接四边形 ABCD
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % 对角线 AC、BD
  \ifnum\showdiagonals>0
    \draw[thick] (A) -- (C);
    \draw[thick] (B) -- (D);
  \fi
  % 内角 ∠DAB 的角弧
  \ifnum\showanglea>0
    \pgfmathsetmacro{\pqaax}{\Dx - (\Ax)}
    \pgfmathsetmacro{\pqaay}{\Dy - (\Ay)}
    \pgfmathsetmacro{\pqabx}{\Bx - (\Ax)}
    \pgfmathsetmacro{\pqaby}{\By - (\Ay)}
    \pgfmathsetmacro{\lenqaa}{sqrt((\pqaax)^2 + (\pqaay)^2)}
    \pgfmathsetmacro{\lenqab}{sqrt((\pqabx)^2 + (\pqaby)^2)}
    \pgfmathsetmacro{\sangqa}{atan2(\pqaay,\pqaax)}
    \pgfmathsetmacro{\erawqa}{atan2(\pqaby,\pqabx)}
    \pgfmathsetmacro{\edifqa}{\erawqa - \sangqa}
    \pgfmathsetmacro{\eangqa}{\sangqa + \edifqa - 360*round(\edifqa/360)}
    \pgfmathsetmacro{\arcrqa}{min(0.45/\figscale, \lenqaa*0.26, \lenqab*0.26)}
    \draw[thick] ({\Ax + \arcrqa*cos(\sangqa)},{\Ay + \arcrqa*sin(\sangqa)}) arc[start angle=\sangqa, end angle=\eangqa, radius=\arcrqa];
  \fi
  % 内角 ∠BCD 的角弧
  \ifnum\showanglec>0
    \pgfmathsetmacro{\pqcax}{\Bx - (\Cx)}
    \pgfmathsetmacro{\pqcay}{\By - (\Cy)}
    \pgfmathsetmacro{\pqcbx}{\Dx - (\Cx)}
    \pgfmathsetmacro{\pqcby}{\Dy - (\Cy)}
    \pgfmathsetmacro{\lenqca}{sqrt((\pqcax)^2 + (\pqcay)^2)}
    \pgfmathsetmacro{\lenqcb}{sqrt((\pqcbx)^2 + (\pqcby)^2)}
    \pgfmathsetmacro{\sangqc}{atan2(\pqcay,\pqcax)}
    \pgfmathsetmacro{\erawqc}{atan2(\pqcby,\pqcbx)}
    \pgfmathsetmacro{\edifqc}{\erawqc - \sangqc}
    \pgfmathsetmacro{\eangqc}{\sangqc + \edifqc - 360*round(\edifqc/360)}
    \pgfmathsetmacro{\arcrqc}{min(0.45/\figscale, \lenqca*0.26, \lenqcb*0.26)}
    \draw[thick] ({\Cx + \arcrqc*cos(\sangqc)},{\Cy + \arcrqc*sin(\sangqc)}) arc[start angle=\sangqc, end angle=\eangqc, radius=\arcrqc];
  \fi
  % 把 BC 延长到 E，画外角 ∠DCE
  \ifnum\showexterior>0
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\Bx)^2 + (\Cy-\By)^2)}
    \pgfmathsetmacro{\extl}{max(\radius*0.42, \bclen*0.3)}
    \pgfmathsetmacro{\Ex}{\Cx + \extl*(\Cx-\Bx)/\bclen}
    \pgfmathsetmacro{\Ey}{\Cy + \extl*(\Cy-\By)/\bclen}
    \draw[thick] (C) -- (\Ex,\Ey);
    \pgfmathsetmacro{\pqeax}{\Dx - (\Cx)}
    \pgfmathsetmacro{\pqeay}{\Dy - (\Cy)}
    \pgfmathsetmacro{\pqebx}{\Ex - (\Cx)}
    \pgfmathsetmacro{\pqeby}{\Ey - (\Cy)}
    \pgfmathsetmacro{\lenqea}{sqrt((\pqeax)^2 + (\pqeay)^2)}
    \pgfmathsetmacro{\lenqeb}{sqrt((\pqebx)^2 + (\pqeby)^2)}
    \pgfmathsetmacro{\sangqe}{atan2(\pqeay,\pqeax)}
    \pgfmathsetmacro{\erawqe}{atan2(\pqeby,\pqebx)}
    \pgfmathsetmacro{\edifqe}{\erawqe - \sangqe}
    \pgfmathsetmacro{\eangqe}{\sangqe + \edifqe - 360*round(\edifqe/360)}
    \pgfmathsetmacro{\arcrqe}{min(0.34/\figscale, \lenqea*0.4, \lenqeb*0.4)}
    \draw[thick] ({\Cx + \arcrqe*cos(\sangqe)},{\Cy + \arcrqe*sin(\sangqe)}) arc[start angle=\sangqe, end angle=\eangqe, radius=\arcrqe];
    \fill (\Ex,\Ey) circle [radius=\dotr pt];
    \node at ({\Ex + 0.18*\radius*(\Cx-\Bx)/\bclen},{\Ey + 0.18*\radius*(\Cy-\By)/\bclen}) {$\labele$};
  \fi
  % 顶点与字母（标签沿半径方向外推，避免压线）
  \fill (A) circle [radius=\dotr pt];
  \node at ({1.15*\Ax},{1.15*\Ay}) {$\labela$};
  \fill (B) circle [radius=\dotr pt];
  \node at ({1.15*\Bx},{1.15*\By}) {$\labelb$};
  \fill (C) circle [radius=\dotr pt];
  \node at ({1.15*\Cx},{1.15*\Cy}) {$\labelc$};
  \fill (D) circle [radius=\dotr pt];
  \node at ({1.15*\Dx},{1.15*\Dy}) {$\labeld$};
  % 圆心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below left=2pt] at (O) {$O$};
  \fi
\end{tikzpicture}
